import * as M from './model.mjs?v=3';
import {opportunitySections,renderOpportunityResults} from './opportunity-ui.mjs?v=3';
import {calculateScenario,yearSeries} from './scenario.mjs?v=3';
import {createExplorer,renderDesignCharts} from './explorer.mjs?v=3';
import {defaults,chemistries,feedstocks,readScenario,saveScenario,validateState} from './state.mjs?v=3';
const weights=Object.fromEntries(window.ELEMENTS.map(e=>[e.sym,e.mass]));
const el=document.querySelector('#calculator');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=4)=>Number.isFinite(n)?new Intl.NumberFormat('en-AU',{maximumSignificantDigits:d}).format(n):'Not calculated';
const pct=n=>fmt(n*100)+'%';
const tn=n=>Math.abs(n)>=1e6?fmt(n/1e6)+' million tonnes':fmt(n)+' tonnes';
let state={...defaults};
try {const saved=sessionStorage.getItem('capacity-lab-v2');if(saved)state=readScenario(saved);else {const earlier=sessionStorage.getItem('capacity-lab-v1');if(earlier){state=readScenario(earlier);state.year=2026;}}if(location.hash.startsWith('#scenario='))state=readScenario(decodeURIComponent(location.hash.slice(10)));}catch(e){document.querySelector('#notice').textContent='Saved scenario could not be read. Defaults are shown. '+e.message;}
const page=document.body.dataset.page;
const field=(key,label,unit='',o={})=>{const scale=o.percent?100:1;return `<label class="field" for="${key}"><span>${esc(label)}</span><span class="input-unit"><input id="${key}" name="${key}" ${o.text?'type="text"':'type="number" inputmode="decimal" min="0"'} ${o.max!==undefined?`max="${o.max}"`:''} step="${o.step||'any'}" value="${esc(o.text?state[key]:state[key]*scale)}" data-key="${key}" data-scale="${scale}"><span>${esc(unit)}</span></span>${o.help?`<span class="help">${o.help}</span>`:''}</label>`;};
const select=(key,label,choices)=>`<label class="field" for="${key}"><span>${label}</span><select id="${key}" data-key="${key}">${choices.map(([v,l])=>`<option value="${esc(v)}" ${state[key]===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const group=(title,fields)=>`<fieldset><legend>${title}</legend><div class="fields">${fields}</div></fieldset>`;
const resultBox=(id,title)=>`<section class="results" aria-label="${title}"><h3>${title}</h3><div id="${id}"></div></section>`;
const panel=(id,title,intro,fields,results)=>`<section class="lab-section" id="${id}"><div class="section-title"><span class="section-number">${esc(id)}</span><h2>${title}</h2></div><p class="section-intro">${intro}</p><div class="workbench"><div>${fields}</div>${results}</div></section>`;
const metric=(label,value,note='')=>`<div class="metric"><dt>${label}</dt><dd>${value}</dd>${note?`<p>${note}</p>`:''}</div>`;
const metrics=(...rows)=>`<dl class="metrics">${rows.join('')}</dl>`;
const table=(caption,head,rows)=>`<div class="table-scroll" tabindex="0" role="region" aria-label="${esc(caption)}"><table><caption>${caption}</caption><thead><tr>${head.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>i===0?`<th scope="row">${c}</th>`:`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const source=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label}</a>`;
const formula=t=>`<p class="formula">${t}</p>`;
const assumption=t=>`<p class="assumption"><strong>Scenario assumption, 7 November 2026.</strong> ${t}</p>`;
let allResults={};
const calculate=()=>calculateScenario(state,weights);
function renderLedger(){
 const node=document.querySelector('#ledger-inputs');if(!node)return;
 const rows=JSON.parse(state.components);
 node.innerHTML=rows.map((r,i)=>`<fieldset><legend>Component ${i+1}</legend><div class="fields">${[['name','Name'],['qty','Number of components'],['kg','Kilograms per component'],['formula','Material formula'],['yield','Net manufacturing yield percent'],['secondary','Qualified secondary share percent']].map(([key,label])=>`<label class="field" for="row-${i}-${key}"><span>${label}</span><input id="row-${i}-${key}" data-row="${i}" data-property="${key}" type="${['name','formula'].includes(key)?'text':'number'}" step="any" value="${esc(['yield','secondary'].includes(key)?r[key]*100:r[key])}"></label>`).join('')}</div><button type="button" class="secondary" data-remove-row="${i}">Remove component ${i+1}</button></fieldset>`).join('');
}
