sections.opportunity=()=>opportunitySections({field,group,panel,resultBox,assumption});
const spaceSections=sections.space;
const powerSections=sections.power;
sections.power=()=>powerSections().replace('<legend>Protected annual allocations</legend>', '<legend>Protected annual allocations</legend>').replace('</fieldset><fieldset><legend>Protected annual allocations', '</fieldset>'+group('Additional clean generation pathways',field('otherCleanGW','Other new clean nameplate capacity','GW',{help:'For example conventional hydro, geothermal or a specified future fusion programme. Storage is excluded.'})+field('otherCleanCF','Capacity factor for this additional generation','%',{percent:true,max:100}))+'<fieldset><legend>Protected annual allocations')+'<p><button type="button" data-action="use-solar-ramp">Use accumulated solar construction in the power budget</button></p>';
sections.space=()=>spaceSections()+panel('propellant','Launch fuel and source production','The payload flights above also require a terrestrial fuel supply. Change the complete launch propellant mass, fuel formula and oxidiser ratio. A synthetic-fuel route can then expose its hydrogen, water, carbon and electricity requirements.',group('Illustrative launch supply inputs',field('propellantTonnes','Complete propellant per total flight','tonnes')+field('flightMultiplier','Total flights divided by useful payload flights','times')+field('propellantFormula','Fuel molecular formula','',{text:true})+field('oxidiserRatio','Oxygen mass divided by fuel mass','times')+field('hydrogenKWhKg','Hydrogen production electricity','kWh/kg H2'))+assumption('These are changeable engineering examples, not a published Starship fuel schedule. Water is process throughput for hydrogen production. It is not automatically consumptive use. Liquefaction, oxygen separation and fuel synthesis need additional process energy.'),resultBox('propellant-result','Terrestrial propellant supply'));
if(el && sections[page])el.innerHTML=sections[page]();
const explorer=createExplorer(el,{page,weights,getState:()=>state,calculate:calculateScenario,series:yearSeries,onChange:patch=>{Object.assign(state,patch);syncForm();}});
renderLedger();
function setResult(id,html){const node=document.getElementById(id);if(node)node.innerHTML=html;}
function update(){
 try{
  const r=calculate();allResults=r;
  document.querySelectorAll('[data-key]').forEach(n=>{if(n!==document.activeElement){const k=n.dataset.key;n.value=typeof state[k]==='number'?state[k]*+(n.dataset.scale||1):state[k];}});
  renderDesignCharts(page,state,r,weights);explorer.render(state,r);document.querySelector('#notice').textContent='';
  try{sessionStorage.setItem('capacity-lab-v2',saveScenario(state));}catch{}
  const {f,c,budget:b}=r;
  if(page==='opportunity')renderOpportunityResults(state,r,{setResult,metrics,metric,table,fmt,tn});
  setResult('propellant-result',metrics(metric('Total launches at selected multiplier',fmt(r.propellant.flights)),metric('Complete propellant',tn(r.propellant.totalT)),metric('Fuel',tn(r.propellant.fuelT)),metric('Oxygen',tn(r.propellant.oxygenT)),metric('Hydrogen in fuel',tn(r.propellant.hydrogenT)),metric('Hydrogen production electricity only',fmt(r.propellant.electrolysisTWh)+' TWh'))+table('Inputs if fuel is made from water and captured carbon dioxide',['Process input','Quantity'],[['Water throughput for hydrogen',tn(r.propellant.waterTForHydrogen)],['Carbon dioxide feed for carbon',tn(r.propellant.co2TForCarbon)]])+`<p>Captured carbon dioxide feed is not a claim of net emissions. The electricity source, process losses and full fuel cycle determine that account. This terrestrial production energy is additional unless already included in the industrial power plan.</p>`);
  setResult('ledger-result',metrics(metric('Finished component mass',tn(r.ledger.massT)),metric('Components included',fmt(r.ledger.items.length)))+table('Element requirements of included components',['Element','Finished','External feed','Primary','Secondary'],Object.entries(r.ledger.totals).map(([e,v])=>[e,tn(v.finished),tn(v.feed),tn(v.primary),tn(v.secondary)]))+`<p>This is a project inventory. Reconcile any included sector allowance before adding it to a global market forecast. Recycling shares still require qualified, allocated supply.</p>`);
  setResult('overview-result',metrics(metric('New robots in this programme this year',fmt(f.units),state.year<state.start?'Modelled manufacture begins in '+state.start+'.':''),metric('Operating fleet',fmt(f.live)),metric('Ground compute electricity',fmt(c.computeTWh)+' TWh/year'),metric('Robot electricity',fmt(c.robotTWh)+' TWh/year'),metric('Protected clean supply gap',fmt(b.protectedGap)+' TWh/year'),metric('Compute and robot supply gap',fmt(b.projectGap)+' TWh/year'))+`<p class="status ${b.projectGap||b.protectedGap?'shortfall':'balanced'}">${b.projectGap||b.protectedGap?'The selected clean supply does not meet all demands.':'The annual clean energy budget covers the selected demands.'} Timing and dependable delivery need separate checks.</p>`+table('Manufacturing horizons',['Year','New robots','Surviving fleet','Ground compute TWh/year'],yearSeries(state,weights).filter(v=>[2026,2027,2028,2029,2031,2032,2036,state.year].includes(v.year)).map(v=>[v.year,fmt(v.f.units),fmt(v.f.live),fmt(v.c.computeTWh)])));
  setResult('power-result',metrics(metric('Rated compute base',fmt(c.ratedGW)+' GW'),metric('Average facility load',fmt(c.averageFacilityGW)+' GW'),metric('Compute electricity',fmt(c.computeTWh)+' TWh/year'),metric('Operating robot fleet',fmt(f.live)),metric('Robot average load',fmt(c.robotGW)+' GW'),metric('Robot electricity',fmt(c.robotTWh)+' TWh/year'))+formula('Compute TWh/year = rated GW × average load fraction × facility power factor × 8.76.')+table('Additional clean generation operating in '+state.year,['Source','New GW','Capacity factor','TWh/year'],r.generation.items.map(v=>[v.name,fmt(v.gw),pct(v.cf),fmt(v.twh)]))+table('Priority allocations and new machine demand',['Account','TWh/year'],[['New clean electricity',fmt(b.supplyTWh)],['Replace fossil generation',fmt(r.allocations.transition)],['Essential development and industry',fmt(r.allocations.essential)],['Replace retired clean supply',fmt(r.allocations.retirement)],['Unmet protected requirement',fmt(b.protectedGap)],['Remaining for new projects',fmt(b.remaining)],['Compute increase above 2025 plus robots',fmt(b.projectTWh)],['Unmet new project requirement',fmt(b.projectGap)],['Remaining annual surplus',fmt(b.surplus)]])+`<p class="status ${b.protectedGap||b.projectGap?'shortfall':'balanced'}">Protected needs retain priority. Storage charging losses, delivery constraints and project-specific additions require further generation beyond this annual end-use budget.</p>`+formula('Generation TWh/year = new nameplate GW × capacity factor × 8.76.')+`<p>Reference rack mass in the rated base: ${tn(r.rackT)} at ${fmt(state.rackKg)} kg per ${fmt(state.rackKW)} kW. ${source('https://www.iea.org/reports/key-questions-on-energy-and-ai/executive-summary','IEA April 2026 energy reference')}.</p>`);
  setResult('construction-result',metrics(metric('Installed capacity accumulated over the chosen years',fmt(r.solarBuildTotal)+' GW'),metric('Last annual installation rate',fmt(r.solarBuilds.at(-1))+' GW/year'))+formula('Annual addition in year n = first annual addition × construction multiplier raised to n minus one. Accumulated capacity is the sum of each year.'));
  setResult('machines-result',metrics(metric('New robots in selected year',fmt(f.units)),metric('Cumulative manufacture',fmt(f.cumulative)),metric('Surviving fleet',fmt(f.live)),metric('Permanent retirements',fmt(f.retired)),metric('Combined annual final-loss fraction',pct(f.hazard)),metric('Mass manufactured this year',tn(f.units*state.robotKg/1000)))+formula('Surviving cohort = new units × annual survival fraction raised to years since manufacture.')+table('All manufacturing years',['Year','Annual new machines','Accumulated manufacture','In service'],(f.rows.length?f.rows:[{year:state.year,units:0,cumulative:0,live:0}]).map(v=>[v.year,fmt(v.units),fmt(v.cumulative),fmt(v.live)])));
  setResult('materials-result',table('Partial new-robot inventory in the selected year',['Element','kg per robot','Finished','External feed','Primary at selected secondary share'],Object.entries(r.inventory).map(([e,v])=>[e,fmt(v.kg),tn(v.finished),tn(v.feed),tn(v.primary)]))+`<p>The inventory includes the selected active cathode and iron nitride magnet inputs. It does not assign the entire battery pack to active material. Defined material mass per robot: ${fmt(Object.values(r.perRobot).reduce((a,b)=>a+b,0))} kg; complete-machine reference: ${fmt(state.robotKg)} kg.</p>`+formula('External feed = finished material ÷ net yield. Primary = external feed × one minus qualified secondary share.')+`<p>Growing market plus additional robot end use in ${state.year}: copper ${tn(r.cuMarket)}; aluminium ${tn(r.alMarket)}. Use the source ledger to inspect the dated market bases and the additional-batch convention.</p>`);
  setResult('repairs-result',metrics(metric('Total service modules',tn(r.service.suppliedT)),metric('Newly supplied module mass',tn(r.service.newT)),metric('Reconditioned mass',tn(r.service.reconditionedT)))+`<p>Replaced modules do not imply replacement of the complete machine. Their element inventory needs its own service bill of materials.</p>`);
  setResult('motors-result',metrics(metric('Remaining rare earth magnets',tn(r.motors.remainingT)),metric('NdPr in those magnets',tn(r.motors.ndprT)),metric('Alternative magnet mass',tn(r.motors.alternativeT)),metric('Iron in Fe16N2 alternative',tn(r.motors.alternativeFeT)))+`<p>NdPr is combined neodymium and praseodymium. Oxide production must be converted to contained metal before comparison.</p>`);
  setResult('solar-result',metrics(metric('Solar nameplate for the chosen energy balance',fmt(r.pv.peakGW)+' GW'),metric('Annual electricity including selected storage losses',fmt(r.pv.annualTWh)+' TWh'),metric('Active absorber material',tn(r.pv.siliconT)),metric('Silver at selected intensity',tn(r.pv.silverT)))+formula('Required solar GW = average load GW × [direct energy share + stored energy share ÷ round-trip efficiency] ÷ capacity factor.')+table('Elements in the selected absorber',['Element','Mass'],Object.entries(r.pv.chemistry.fractions).map(([e,v])=>[e,tn(r.pv.siliconT*v)]))+`<p>These quantities describe the selected active absorber and silver inputs. Frames, glass, supports, contacts and networks need their own inventory.</p>`);
  setResult('storage-result',metrics(metric('Usable AC delivery',fmt(r.store.usableGWh)+' GWh'),metric('Nominal stored energy',fmt(r.store.nominalGWh)+' GWh'),metric('Recharge electricity after delivery',fmt(r.store.rechargeGWh)+' GWh'),metric('Round-trip efficiency',pct(r.store.roundTrip)))+formula('Nominal GWh = buffered GW × hours ÷ usable state-of-charge share ÷ discharge efficiency.')+`<p>At 120 GW, four hours supplies 480 GWh. At the current design settings, the nominal capacity also covers the stated discharge losses and unused reserve.</p>`);
  const packKg=r.store.nominalGWh*1e9/state.packWhKg;
  setResult('chemistry-result',metrics(metric('Molar mass',fmt(r.gridBattery.formula.molarMass)+' g/mol'),metric('Active cathode per kWh',fmt(r.gridBattery.kgPerKWh)+' kg'),metric('Complete grid pack allowance',tn(packKg/1000)),metric('Active grid cathode',tn(r.gridBattery.activeKg/1000)))+table('Elements in the nominal grid-storage cathode',['Element','Mass fraction','Tonnes'],Object.entries(r.gridBattery.elements).map(([e,kg])=>[e,pct(r.gridBattery.formula.fractions[e]),tn(kg/1000)]))+`<p>${r.gridBattery.activeKg>packKg?'<strong class="shortfall">The active cathode exceeds the complete-pack mass allowance. These inputs are inconsistent.</strong>':'The rest of the complete-pack mass allowance is '+tn((packKg-r.gridBattery.activeKg)/1000)+'. Its components still need an inventory.'}</p>`+formula('Active kg = nominal kWh × 1,000 ÷ active-material Ah/kg ÷ cell volts. Element kg = active kg × elemental mass fraction.'));
  try{const day=M.dailySolar({loadGW:state.pvLoadGW,peakGW:r.pv.peakGW,cf:state.pvCF,usableGWh:r.store.nominalGWh*state.dod,charge:state.charge,discharge:state.discharge});setResult('day-result',metrics(metric('Unserved energy in the repeated day',fmt(day.unservedGWh)+' GWh'),metric('Curtailed energy',fmt(day.curtailedGWh)+' GWh'))+table('Illustrative final daily cycle',['Hour','Solar GW','Load GW','Stored GWh','Unserved GWh'],day.rows.map(v=>[`${String(v.hour).padStart(2,'0')}:00`,fmt(v.solarGW),fmt(v.loadGW),fmt(v.storedGWh),fmt(v.unservedGWh)])));}catch(e){setResult('day-result',`<p class="shortfall">${esc(e.message)}</p>`);}
  setResult('ore-result',metrics(metric('Target element in pure formula compound',pct(r.ore.elementFraction)),metric('Contained element grade of ore',pct(r.ore.containedGrade)),metric('Ore throughput for selected annual metal',tn(r.ore.oreT)))+formula('Ore tonnes = primary metal tonnes ÷ formula share of ore ÷ target element share of formula ÷ combined recovery.')+table('Composition of source compound',['Element','Mass fraction'],Object.entries(r.ore.formula.fractions).map(([e,v])=>[e,pct(v)]))+`<p>Other elements in the feed are not automatically saleable co-products. Actual mineralogy, impurities, processing route, water and energy need project evidence.</p>`);
  setResult('supply-result',metrics(metric('Required compound annual output growth',pct(r.cap.requiredCagr)),metric('Output under selected expansion',tn(r.cap.projected)+'/year'),metric('Annual output gap',tn(r.cap.gap)),metric('Increase over present annual output',tn(r.cap.increase)))+table('Paper production benchmarks for 2025',['Material and basis','World annual output','Australian annual output'],[['Mined copper content','23 million tonnes','730,000 tonnes'],['Refined copper including recycled feed','29 million tonnes','Separate refinery inventory required'],['Primary aluminium','74 million tonnes','1.57 million tonnes'],['Bauxite ore','450 million tonnes','102.5 million tonnes'],['Contained iron in mine output','1.6 billion tonnes','596 million tonnes'],['Contained lithium','314,000 tonnes','118,000 tonnes']])+`<p>Geoscience Australia, 12 October 2026, and USGS 2026. Current output is not spare capacity.</p>`);
  setResult('refinery-result',metrics(metric('Annual production at selected ramp',tn(r.refinery.output)),metric('Allocated annual product',tn(r.refinery.available)))+formula('Allocated product = annual nameplate × achieved fraction × project allocation.'));
  setResult('market-result',table('Annual metal in end uses',['Material','Growing market base','With incremental robot batch'],[['Copper',tn(r.cuBase),tn(r.cuMarket)],['Aluminium',tn(r.alBase),tn(r.alMarket)]])+`<p>These are end-use demand quantities. Primary production, secondary production and external factory feed have their own process boundaries. S and P Global January 2026 and McKinsey July 2025 provide the original anchors. Higher infrastructure buildouts require replacing their relevant sector assumptions with project inventories.</p>`);
  setResult('orbit-result',metrics(metric('Complete-system mass manufactured this year',tn(r.orbit.payloadT)),metric('Successful payload flights required',fmt(r.orbit.flights)),metric('Electrical input for selected installation',fmt(r.orbit.electricGW)+' GW'),metric('Solar collecting area',fmt(r.orbit.solarAreaM2/1e6)+' km²'),metric('Heat to reject',fmt(r.orbit.heatGW)+' GW'),metric('Emitting radiator area',fmt(r.orbit.radiatorAreaM2/1e6)+' km²'))+formula('Radiator emitting area = heat watts ÷ emissivity ÷ Stefan-Boltzmann constant ÷ surface kelvin to the fourth power.')+`<p>The heat boundary conservatively includes all system electricity. Area is emitting area, not necessarily panel footprint. Orbit, eclipses, degradation, storage, radiator background and layout require a complete design. Manufacturing and launch energy belong to their terrestrial supply chains.</p>`);
  setResult('beam-result',metrics(metric('Generator electricity required',fmt(r.beam.sourceGW)+' GW'),metric('Conversion and transmission losses',fmt(r.beam.lossGW)+' GW'))+formula('Source power = delivered power ÷ end-to-end electrical efficiency.')+`<p>Ground-delivered space power can enter the terrestrial budget only when delivered, after losses. Local orbital compute is not also credited as electricity delivered to Earth.</p>`);
  const popCu=M.procurement(r.pop.annualRobots*state.cuKg/1000,state.yield,state.secondary),popAl=M.procurement(r.pop.annualRobots*state.alKg/1000,state.yield,state.secondary);
  setResult('australia-result',metrics(metric('Population in the selected year',fmt(r.population)),metric('Additional people',fmt(r.pop.extra)),metric('Population-only additional dwelling equivalents',fmt(r.pop.homes)),metric('Civic robot requirement in selected year',fmt(r.pop.fleet)),metric('Annual manufacture during initial build',fmt(r.pop.annualRobots)),metric('Material in completed robot base',tn(r.pop.stockT)),metric('Annual operating electricity at chosen wall power',fmt(r.pop.robotTWh)+' TWh'))+table('Annual domestic robot material',['Material','External feed','Primary at selected secondary share'],[['Copper',tn(popCu.feed),tn(popCu.primary)],['Aluminium',tn(popAl.feed),tn(popAl.primary)]])+`<p>Existing housing shortages, demolitions and changing household size are additional to the population-only dwelling calculation. Actual permanent machine losses require further units. Australian civic robots can maintain housing, farms, water, roads and emergency services.</p>`);
  const siteRated=state.sites*state.siteRatedKW/1e6,sitePower=M.compute({ratedGW:siteRated,util:state.util,pue:state.pue,robotFleet:0,robotW:0});
  setResult('sites-result',metrics(metric('Initial complete-site allowance', 'A$'+fmt(state.sites*state.siteCostAUD/1e9)+' billion'),metric('Rated distributed compute',fmt(siteRated*1000)+' MW'),metric('Annual facility electricity',fmt(sitePower.computeTWh)+' TWh'),metric('Projected residents per site',fmt(r.population/state.sites)))+`<p>Owners and communities retain operating authority. GAJRA Earth connects that missing middle globally. Brisbane 2032 provides a deadline to establish skills, useful equipment and ongoing local ownership rather than an event-only installation.</p>`);
  const exported=Math.max(0,r.cuMarket-state.marketCu2025)*state.exportShare;
  setResult('exports-result',metrics(metric('Added annual global copper end use',tn(Math.max(0,r.cuMarket-state.marketCu2025))),metric('Selected export sales target by copper content',tn(exported)+'/year'),metric('Relative to 2025 Australian mine output',pct(exported/730000)))+`<p>This compares contained metal. Refining, component manufacture and recovery change the source mineral and power required. Secure domestic supply agreements alongside export customers.</p>`);
  document.querySelector('#scenario-status').textContent=`Year in view: ${state.year}. Graphs cover 2026 to ${Math.max(state.year,state.chartEndYear)}. Displayed results are rounded.`;
 }catch(e){explorer.pause(e.message);document.querySelector('#notice').textContent=e.message;document.querySelector('#scenario-status').textContent='Complete valid scenario inputs to calculate.';document.querySelectorAll('.results > div').forEach(n=>{n.innerHTML='<p>Results paused until the scenario inputs are valid.</p>';});}
}
function syncForm(){document.querySelectorAll('[data-key]').forEach(n=>{const key=n.dataset.key;n.value=typeof state[key]==='number'?state[key]*+(n.dataset.scale||1):state[key];});renderLedger();update();}
document.addEventListener('input',e=>{if(e.target.dataset.row===undefined)return;const i=+e.target.dataset.row,key=e.target.dataset.property,rows=JSON.parse(state.components);if(['name','formula'].includes(key))rows[i][key]=e.target.value;else{if(e.target.value==='')return;rows[i][key]=Number(e.target.value)/(['yield','secondary'].includes(key)?100:1);}state.components=JSON.stringify(rows);update();});
document.addEventListener('click',e=>{const i=e.target.closest('[data-remove-row]')?.dataset.removeRow;if(i===undefined)return;const rows=JSON.parse(state.components);rows.splice(+i,1);state.components=JSON.stringify(rows);renderLedger();update();});
document.addEventListener('input',e=>{const key=e.target.dataset.key;if(!key)return;if(typeof state[key]==='number'){if(e.target.value===''){document.querySelector('#notice').textContent='Complete this value to calculate the scenario.';explorer.pause('Complete the input to update the graphs.');return;}state[key]=Number(e.target.value)/+(e.target.dataset.scale||1);}else state[key]=e.target.value;update();});
document.addEventListener('change',e=>{
 if(e.target.id==='chemistry-preset'&&chemistries[e.target.value]){const p=chemistries[e.target.value];Object.assign(state,{chemistry:p.formula,ahkg:p.ahkg,voltage:p.voltage});syncForm();}
 if(e.target.id==='feedstock-preset'&&feedstocks[e.target.value]){const p=feedstocks[e.target.value];Object.assign(state,{material:p.element,feedFormula:p.formula,grade:p.grade,recovery:p.recovery});syncForm();}
});
function download(name,text,type){const a=document.createElement('a');const u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
document.addEventListener('click',async e=>{
 const a=e.target.closest('[data-action]')?.dataset.action;if(!a)return;
 try{
  if(a==='au-pilot'){Object.assign(state,{auModuleM2:4500,auSupportM2:1500});syncForm();}
  if(a==='au-modular'){Object.assign(state,{auModuleM2:20000,auSupportM2:5000});syncForm();}
  if(a==='au-faster'){Object.assign(state,{auModuleM2:20000,auSupportM2:5000,auFactoryGrowth:1.54});syncForm();}
  if(a==='reset'){state={...defaults};syncForm();}
  if(a==='add-component'){const rows=JSON.parse(state.components);if(rows.length>=100)throw Error('The ledger supports at most 100 components.');rows.push({name:'New component',qty:1,kg:1,formula:'Cu',yield:state.yield,secondary:state.secondary});state.components=JSON.stringify(rows);renderLedger();update();}
  if(a==='load-components'){
   const r=calculate(),rows=[];
   for(const e of ['Cu','Al','Fe'])rows.push({name:'New robot '+e,qty:r.f.units,kg:state[e==='Cu'?'cuKg':e==='Al'?'alKg':'feKg']*state.materialEfficiency,formula:e,yield:state.yield,secondary:state.secondary});
   rows.push({name:'New robot active cathode',qty:r.f.units,kg:r.batteryRobot.activeKg,formula:state.chemistry,yield:state.yield,secondary:state.secondary},{name:'Selected solar active absorber',qty:1,kg:r.pv.siliconT*1000,formula:state.pvFormula,yield:state.yield,secondary:state.secondary},{name:'Selected storage active cathode',qty:1,kg:r.gridBattery.activeKg,formula:state.chemistry,yield:state.yield,secondary:state.secondary});
   if(r.motors.alternativeT)rows.push({name:'Alternative iron nitride magnets',qty:1,kg:r.motors.alternativeT*1000,formula:'Fe16N2',yield:state.yield,secondary:state.secondary});
   state.components=JSON.stringify(rows);renderLedger();update();document.querySelector('#scenario-status').textContent='Ledger replaced with linked partial inventories. Add the remaining components.';
  }
  if(a==='export'){download(`capacity-scenario-${state.year}.json`,saveScenario(state),'application/json');}
  if(a==='import')document.querySelector('#import-file').click();
  if(a==='share'){const url=new URL(location.href);url.hash='scenario='+encodeURIComponent(saveScenario(state));await navigator.clipboard.writeText(url.href);document.querySelector('#scenario-status').textContent='Scenario link copied. Its inputs are included in the link.';}
  if(a==='csv'){
    const r=calculate();const rows=[['quantity','value','unit'],['target_year',state.year,'calendar year'],['annual_new_robots',r.f.units,'machines/year'],['operating_fleet',r.f.live,'machines'],['compute_facility_energy',r.c.computeTWh,'TWh/year'],['robot_energy',r.c.robotTWh,'TWh/year'],['new_clean_energy',r.budget.supplyTWh,'TWh/year'],['protected_energy_gap',r.budget.protectedGap,'TWh/year'],['new_project_energy_gap',r.budget.projectGap,'TWh/year'],['solar_nameplate',r.pv.peakGW,'GW'],['nominal_storage',r.store.nominalGWh,'GWh'],['source_ore',r.ore.oreT,'tonnes/year'],['orbital_payload',r.orbit.payloadT,'tonnes/year']];
    for(const [k,v] of Object.entries(r.inventory))rows.push([k+'_robot_finished',v.finished,'tonnes/year'],[k+'_robot_primary',v.primary,'tonnes/year']);
    for(const [k,v] of Object.entries(r.ledger.totals))rows.push([k+'_project_ledger_finished',v.finished,'tonnes'],[k+'_project_ledger_primary',v.primary,'tonnes']);
    download(`capacity-results-${state.year}.csv`,rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv');
  }
  if(a==='use-load'){const r=calculate();state.pvLoadGW=r.c.averageFacilityGW+r.c.robotGW;state.bufferLoadGW=state.pvLoadGW;syncForm();}
  if(a==='use-solar-ramp'){state.solarGW=calculate().solarBuildTotal;state.powerTargetYear=2025+state.solarBuildYears;syncForm();document.querySelector('#scenario-status').textContent='The solar construction total is now the capacity at power plan year '+state.powerTargetYear+'.';}
  if(a==='use-material'){const r=calculate();if(!r.inventory[state.material])throw Error('No linked robot requirement is specified for this element. Enter an annual requirement.');state.primaryT=r.inventory[state.material].primary;syncForm();}
  if(a==='population-2032'){Object.assign(state,{popTarget:30045900,populationTargetYear:2032,buildYears:6,year:2032});syncForm();}
  if(a==='population-2036'){Object.assign(state,{popTarget:31470400,populationTargetYear:2036,buildYears:10,year:2036});syncForm();}
 }catch(err){document.querySelector('#notice').textContent=err.message;}
});
document.querySelector('#import-file')?.addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>200000)throw Error('Choose a scenario JSON file smaller than 200 KB.');state=readScenario(await file.text());syncForm();document.querySelector('#scenario-status').textContent='Scenario imported.';}catch(err){document.querySelector('#notice').textContent=err.message;}e.target.value='';});
if(document.querySelector('#periodic')){
 const grid=document.querySelector('#periodic');
 grid.innerHTML=window.ELEMENTS.map(e=>`<button type="button" class="element ${e.cat}" style="grid-column:${e.xpos};grid-row:${e.ypos}" data-element="${e.sym}" aria-label="${e.name}, atomic number ${e.z}"><span>${e.z}</span><strong>${e.sym}</strong></button>`).join('');
 grid.addEventListener('click',e=>{const sym=e.target.closest('[data-element]')?.dataset.element;const item=window.ELEMENTS.find(x=>x.sym===sym);if(item)document.querySelector('#element-result').innerHTML=`<h3>${esc(item.name)} ${item.sym}</h3><p>Atomic number ${item.z}. Atomic mass used in calculations ${item.mass} unified atomic mass units. ${item.radioactive?'Radioactive element; the tabulated mass may represent an isotope.':''} ${source('https://auraofintelligence.github.io/extreme-matter-atlas/periodic-table.html','Explore the public Extreme Matter Atlas')}.</p>`;});
}
update();
window.capacityLab={get state(){return {...state}},results:()=>calculate(),series:()=>yearSeries(state,weights),setYear:year=>{state.year=year;syncForm();}};
